function systemInstruction() {
  return "You are a precise release notes writer. Keep entries short.";
}

function formatChangelog(entries) {
  return entries.map(e => "- " + e).join("\n");
}

function composePrompt(entries, audience) {
  return [
    { role: "system", content: systemInstruction() },
    { role: "user", content: "Audience: " + audience + "\n\n" + formatChangelog(entries) }
  ];
}

const summaryMessages = await getPrompt("summarize-ticket", { ticketId: "T-482" });
const summaryText = summaryMessages[summaryMessages.length - 1].content.text;

const replyMessages = await getPrompt("draft-customer-reply", {
  ticketSummary: summaryText,
  tone: "empathetic"
});

async function composeReviewPrompt(fileUri) {
  const resource = await readResource(fileUri);

  const system = "You are a careful code reviewer. Point out bugs and unclear naming.";
  const userText = "Review this file:\n\n" + resource.text;

  return [
    { role: "system", content: system },
    { role: "user", content: userText }
  ];
}

async function composeSupportReply(ticketUri, tone) {
  const system = "You are a support agent. Be clear, honest, and brief.";

  const ticket = await readResource(ticketUri);

  const template = await getPromptTemplate("support-reply-template");
  const filled = template.fill({ ticketBody: ticket.text, tone: tone });

  return [
    { role: "system", content: system },
    { role: "user", content: filled }
  ];
}

async function composeSafely(ticketUri, tone) {
  const ticket = await readResource(ticketUri);
  if (!ticket || !ticket.text) {
    throw new Error("Cannot compose reply: ticket resource returned no content");
  }
  return composeSupportReply(ticketUri, tone);
}

async function composePrDescription(diffUri, styleName) {
  const system = "You write clear, honest pull request descriptions. No exaggeration.";

  const diff = await readResource(diffUri);
  const style = await getPromptTemplate(styleName);
  const filled = style.fill({ diffText: diff.text });

  return [
    { role: "system", content: system },
    { role: "user", content: filled }
  ];
}

const messages = await composePrDescription(
  "git://repo/pull/482/diff",
  "pr-description-concise"
);

// One reasonable answer
async function composeMeetingSummary(transcriptUri, lengthTemplate) {
  const system = "Summarize neutrally. Do not add opinions.";
  const transcript = await readResource(transcriptUri);
  const template = await getPromptTemplate(lengthTemplate);
  const filled = template.fill({ transcriptText: transcript.text });
  return [
    { role: "system", content: system },
    { role: "user", content: filled }
  ];
}
